 if($action==='servers'){$q=$db->prepare("SELECT id,name,description,type,status,member_count FROM servers WHERE owner_id=? AND status<>'archived' ORDER BY name");$q->execute([$uid]);echo json_encode(['success'=>true,'servers'=>$q->fetchAll(PDO::FETCH_ASSOC)]);exit;}
 $sid=(int)($_GET['server_id']??0);if(!$sid||!owned($db,$sid,$uid)){http_response_code(403);echo json_encode(['error'=>'You do not own this server']);exit;}
