 if($action==='permissions'){$q=$db->prepare("SELECT s.id,s.name,COALESCE(fp.allow_member_invites,1) allow_member_invites,COALESCE(fp.allow_member_messages,1) allow_member_messages,COALESCE(fp.allow_voice,1) allow_voice,COALESCE(fp.allow_polls,1) allow_polls,COALESCE(fp.allow_files,1) allow_files FROM servers s LEFT JOIN facilitator_server_permissions fp ON fp.server_id=s.id WHERE s.id=? AND s.owner_id=?");$q->execute([$sid,$uid]);echo json_encode(['success'=>true,'permissions'=>$q->fetch(PDO::FETCH_ASSOC)]);exit;}
 if($action==='resources'){$q=$db->prepare("SELECT f.id,f.file_name,f.original_name,f.file_path,f.file_size,f.mime_type,f.created_at,u.username,c.name channel_name FROM uploaded_files f JOIN users u ON u.id=f.uploader_id LEFT JOIN channels c ON c.id=f.channel_id WHERE f.server_id=? AND f.deleted_at IS NULL ORDER BY f.created_at DESC");$q->execute([$sid]);echo json_encode(['success'=>true,'files'=>$q->fetchAll(PDO::FETCH_ASSOC)]);exit;}
 if($action==='workspace'){try{$q=$db->prepare("SELECT d.id,'document' item_type,d.title item_name,d.updated_at created_at,d.visibility,w.channel_id,c.name channel_name FROM collab_documents d JOIN collab_workspaces w ON w.id=d.workspace_id LEFT JOIN channels c ON c.id=w.channel_id WHERE w.server_id=? AND d.visibility='public' UNION ALL SELECT b.id,'whiteboard',b.title,b.updated_at,b.visibility,w2.channel_id,c2.name FROM collab_whiteboards b JOIN collab_workspaces w2 ON w2.id=b.workspace_id LEFT JOIN channels c2 ON c2.id=w2.channel_id WHERE w2.server_id=? AND b.visibility='public' ORDER BY created_at DESC");$q->execute([$sid,$sid]);echo json_encode(['success'=>true,'items'=>$q->fetchAll(PDO::FETCH_ASSOC)]);}catch(Throwable $e){error_log('[facilitator workspace] '.$e->getMessage());echo json_encode(['success'=>true,'items'=>[]]);}exit;}
 if($action==='activity'){$q=$db->prepare("SELECT u.id,u.username,u.full_name,COUNT(DISTINCT m.id) messages,COUNT(DISTINCT srp.id) voice_joins,COALESCE(SUM(CASE WHEN srp.joined_at IS NOT NULL THEN TIMESTAMPDIFF(SECOND,srp.joined_at,COALESCE(srp.left_at,NOW())) ELSE 0 END),0) voice_seconds,MAX(m.created_at) last_message FROM server_members sm JOIN users u ON u.id=sm.user_id LEFT JOIN channels c ON c.server_id=sm.server_id LEFT JOIN messages m ON m.channel_id=c.id AND m.sender_id=u.id AND m.is_deleted=0 LEFT JOIN study_rooms sr ON sr.server_id=sm.server_id LEFT JOIN study_room_participants srp ON srp.room_id=sr.id AND srp.user_id=u.id WHERE sm.server_id=? AND u.id<>? GROUP BY u.id,u.username,u.full_name ORDER BY messages DESC");$q->execute([$sid,$uid]);echo json_encode(['success'=>true,'users'=>$q->fetchAll(PDO::FETCH_ASSOC)]);exit;}
 if($action==='reports'){$q=$db->prepare("SELECT r.*,ru.username reporter_username,COALESCE(ru.full_name,ru.username) reporter_name,tu.username reported_username,COALESCE(tu.full_name,tu.username) reported_name,m.content message_content,c.name channel_name FROM content_reports r JOIN users ru ON ru.id=r.reporter_id LEFT JOIN users tu ON tu.id=r.reported_user_id LEFT JOIN messages m ON m.id=r.message_id LEFT JOIN channels c ON c.id=m.channel_id WHERE r.server_id=? ORDER BY FIELD(r.status,'pending','reviewing','resolved','dismissed'),r.created_at DESC");$q->execute([$sid]);echo json_encode(['success'=>true,'reports'=>$q->fetchAll(PDO::FETCH_ASSOC)]);exit;}
 if($action==='banned'){$q=$db->prepare("SELECT ma.id,ma.target_user_id,u.username,u.full_name,ma.reason,ma.created_at FROM moderation_actions ma JOIN users u ON u.id=ma.target_user_id WHERE ma.server_id=? AND ma.action_type='ban' AND ma.is_active=1 AND (ma.expires_at IS NULL OR ma.expires_at>NOW()) ORDER BY ma.created_at DESC");$q->execute([$sid]);echo json_encode(['success'=>true,'users'=>$q->fetchAll(PDO::FETCH_ASSOC)]);exit;}
