AuthMiddleware::verifyCsrf();$b=body();$sid=(int)($b['server_id']??0);if(!$sid||!owned($db,$sid,$uid)){http_response_code(403);echo json_encode(['error'=>'You can only manage servers you own']);exit;}
try{
 if($action==='permissions'){$scope=(string)($b['apply_scope']??'server');$vals=[!empty($b['allow_member_invites'])?1:0,!empty($b['allow_member_messages'])?1:0,!empty($b['allow_voice'])?1:0,!empty($b['allow_polls'])?1:0,!empty($b['allow_files'])?1:0];$targets=[$sid];if($scope==='all'){$q=$db->prepare("SELECT id FROM servers WHERE owner_id=? AND status<>'archived'");$q->execute([$uid]);$targets=array_map('intval',$q->fetchAll(PDO::FETCH_COLUMN));}$q=$db->prepare("INSERT INTO facilitator_server_permissions(server_id,allow_member_invites,allow_member_messages,allow_voice,allow_polls,allow_files,updated_by) VALUES(?,?,?,?,?,?,?) ON DUPLICATE KEY UPDATE allow_member_invites=VALUES(allow_member_invites),allow_member_messages=VALUES(allow_member_messages),allow_voice=VALUES(allow_voice),allow_polls=VALUES(allow_polls),allow_files=VALUES(allow_files),updated_by=VALUES(updated_by),updated_at=CURRENT_TIMESTAMP");foreach($targets as $target){if(!owned($db,$target,$uid))continue;$q->execute([$target,...$vals,$uid]);}echo json_encode(['success'=>true,'updated_servers'=>count($targets)]);exit;}
 if($action==='announcement'){$title=trim((string)($b['title']??''));$message=trim((string)($b['message']??''));if($title===''||$message===''){throw new InvalidArgumentException('Title and message are required');}$db->beginTransaction();$cid=announcementChannel($db,$sid,$uid);$text="📢 ".$title."\n\n".$message;$q=$db->prepare("INSERT INTO messages(channel_id,sender_id,content,content_type) VALUES(?,?,?,'text')");$q->execute([$cid,$uid,$text]);$link=(defined('BASE_URL')?BASE_URL:'').'/modules/chat/chat.php?server_id='.$sid.'&channel_id='.$cid;$q=$db->prepare("INSERT INTO notifications(recipient_id,actor_id,type,title,body,link_url,icon) SELECT sm.user_id,?,'class_update',?,?,?,'📢' FROM server_members sm WHERE sm.server_id=? AND sm.user_id<>?");$q->execute([$uid,$title,$message,$link,$sid,$uid]);$db->commit();echo json_encode(['success'=>true,'channel_id'=>$cid]);exit;}
 if($action==='settings'){$name=trim((string)($b['name']??''));$desc=trim((string)($b['description']??''));$visibility=(string)($b['visibility']??'private');$locked=!empty($b['lock_channels'])?1:0;if($name==='')throw new InvalidArgumentException('Server name is required');$cols=[];foreach($db->query('SHOW COLUMNS FROM servers')->fetchAll(PDO::FETCH_ASSOC) as $r)$cols[$r['Field']]=true;$sets=['name=?','description=?'];$p=[$name,$desc];if(isset($cols['visibility'])){$sets[]='visibility=?';$p[]=$visibility;}elseif(isset($cols['type'])){$sets[]='type=?';$p[]=$visibility==='public'?'public':'private';}$p[]=$sid;$db->prepare('UPDATE servers SET '.implode(',',$sets).' WHERE id=?')->execute($p);$db->prepare('UPDATE channels SET is_locked=? WHERE server_id=? AND type<>\'announcement\'')->execute([$locked,$sid]);announcementChannel($db,$sid,$uid);echo json_encode(['success'=>true]);exit;}
 if($action==='moderate'){$target=(int)($b['target_user_id']??0);$kind=(string)($b['kind']??'');if(!in_array($kind,['mute','suspend','kick','ban','unmute','unsuspend','unban'],true)||!$target)throw new InvalidArgumentException('Invalid moderation action');if($target===$uid)throw new InvalidArgumentException('You cannot moderate yourself');$reason=trim((string)($b['reason']??''));$reportId=(int)($b['report_id']??0);$mins=isset($b['duration_mins'])?(int)$b['duration_mins']:null;if(in_array($kind,['mute','suspend'],true)&&!$mins)$mins=1440;$expires=$mins?date('Y-m-d H:i:s',time()+$mins*60):null;$dbKind=$kind;$tag='';$db->beginTransaction();$db->prepare("INSERT INTO moderation_actions(moderator_id,target_user_id,server_id,action_type,reason,duration_mins,expires_at,is_active) VALUES(?,?,?,?,?,?,?,1)")->execute([$uid,$target,$sid,$dbKind,$tag.$reason,$mins,$expires]);if($kind==='ban'||$kind==='kick')$db->prepare('DELETE FROM server_members WHERE server_id=? AND user_id=?')->execute([$sid,$target]);if($kind==='unban')$db->prepare("UPDATE moderation_actions SET is_active=0 WHERE server_id=? AND target_user_id=? AND action_type='ban'")->execute([$sid,$target]);if($kind==='unmute')$db->prepare("UPDATE moderation_actions SET is_active=0 WHERE server_id=? AND target_user_id=? AND action_type='mute'")->execute([$sid,$target]);if($kind==='unsuspend')$db->prepare("UPDATE moderation_actions SET is_active=0 WHERE server_id=? AND target_user_id=? AND action_type='suspend'")->execute([$sid,$target]);if($reportId){$q=$db->prepare("UPDATE content_reports SET status='resolved',resolved_by=?,resolved_at=NOW(),resolution_note=? WHERE id=? AND server_id=? AND status IN ('pending','reviewing')");$q->execute([$uid,ucfirst($kind).($mins?' for '.$mins.' minutes':''),$reportId,$sid]);}$db->commit();echo json_encode(['success'=>true]);exit;}
 http_response_code(400);echo json_encode(['error'=>'Unknown action']);
